// @pit: {"label": "Prepare delivery and open the pull request referencing issue 396"}
async ({ delivery: { prepare, listChangedFiles, openPullRequest } }, p: { body: string }) => {
  const ready = await prepare();
  const { files } = await listChangedFiles({ includeDeleted: true });
  const pr = await openPullRequest({
    branch: "durable-collapse-finished-runs",
    files,
    message: "feat(durable): collapse finished runs' tool calls to their labels after each run\n\nRefs #396",
    title: "feat(durable): collapse finished runs' tool calls to their labels after each run",
    body: p.body,
  });
  return { ready: (ready as any).ready, files, pr };
}
